-      count = Math.min(
-        count,
-        Math.floor((span(scale.domain()) / minStep) || 1) + 1
-      );
+      const domain = scale.domain(),
+            lo = Math.min(domain[0], peek(domain)),
+            hi = Math.max(domain[0], peek(domain));
